use vstd::prelude::*;

verus! {
    // Compute the minimum element of a non‐empty vector of i8.
    // We return `res` such that:
    //   1. res is equal to one of the entries of `a`, and
    //   2. for every j < a.len(), res <= a[j].
    fn min(a: Vec<i8>) -> (res: i8)
        requires
            a.len() > 0,
        ensures
            // res equals some element of a
            exists k: usize, k < a.len() && res == a[k],
        ensures
            // res is less than or equal to every element of a
            forall j: usize, j < a.len() ==> res <= a[j],
    {
        // We scan from index 1 up to a.len()-1, maintaining:
        //   idx ≤ a.len(),
        //   for all j < idx, res ≤ a[j],
        //   exists k < idx, res == a[k].
        let mut idx: usize = 1;
        let mut res: i8 = a[0];
        while idx < a.len()
            invariant
                idx <= a.len(),
                forall j: usize, j < idx ==> res <= a[j],
                exists k: usize, k < idx && res == a[k],
            decreases a.len() - idx,
        {
            let v: i8 = a[idx];
            if v < res {
                res = v;
            }
            idx = idx + 1;
        }
        // At the end, idx == a.len(), so the invariants
        // give exactly the postconditions we want.
        res
    }
}

